# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def kthLargestPerfectSubtree(self, root: 'TreeNode', k: int) -> int:
        perfect_sizes = []

        # Returns height of perfect subtree rooted at node, or -1 if not perfect
        def dfs(node):
            if not node:
                return 0
            lh = dfs(node.left)
            rh = dfs(node.right)
            if lh != -1 and rh != -1 and lh == rh:
                h = lh + 1
                perfect_sizes.append((1 << h) - 1)
                return h
            return -1

        dfs(root)
        perfect_sizes.sort(reverse=True)
        if len(perfect_sizes) < k:
            return -1
        return perfect_sizes[k - 1]

#include <vector>
#include <algorithm>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
    std::vector<int> perfect_sizes;
    int dfs(TreeNode* node) {
        if (!node) return 0;
        int lh = dfs(node->left);
        int rh = dfs(node->right);
        if (lh != -1 && rh != -1 && lh == rh) {
            int h = lh + 1;
            perfect_sizes.push_back((1 << h) - 1);
            return h;
        }
        return -1;
    }
public:
    int kthLargestPerfectSubtree(TreeNode* root, int k) {
        perfect_sizes.clear();
        dfs(root);
        std::sort(perfect_sizes.rbegin(), perfect_sizes.rend());
        if ((int)perfect_sizes.size() < k) return -1;
        return perfect_sizes[k - 1];
    }
};

import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    private List<Integer> perfectSizes = new ArrayList<>();

    public int kthLargestPerfectSubtree(TreeNode root, int k) {
        perfectSizes.clear();
        dfs(root);
        perfectSizes.sort(Collections.reverseOrder());
        if (perfectSizes.size() < k) return -1;
        return perfectSizes.get(k - 1);
    }

    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int lh = dfs(node.left);
        int rh = dfs(node.right);
        if (lh != -1 && rh != -1 && lh == rh) {
            int h = lh + 1;
            perfectSizes.add((1 << h) - 1);
            return h;
        }
        return -1;
    }
}

var kthLargestPerfectSubtree = function(root, k) {
    const perfectSizes = [];

    function dfs(node) {
        if (!node) return 0;
        const lh = dfs(node.left);
        const rh = dfs(node.right);
        if (lh !== -1 && rh !== -1 && lh === rh) {
            const h = lh + 1;
            perfectSizes.push((1 << h) - 1);
            return h;
        }
        return -1;
    }

    dfs(root);
    perfectSizes.sort((a, b) => b - a);
    if (perfectSizes.length < k) return -1;
    return perfectSizes[k - 1];
};
